cd /app && cat > ./gerar_tmp.ts <<'EOF'
import { LOCAIS, renderPagina, tituloDaPagina } from './base44/shared/eletricistaConteudo.ts';
import { homeHtml } from './base44/shared/homeConteudo.ts';
const SITE = 'https://www.mestredosreparos.app.br';
const conteudo = {"intro":"A Mestre dos Reparos é referência em serviços de eletricista e manutenção em toda a cidade de Barueri. Contamos com um time de profissionais experientes prontos para atender qualquer demanda técnica com excelência.\nTrabalhamos sob as normas da NBR 5410 para oferecer soluções seguras a residências e comércios locais. Com nota fiscal e garantia de 90 dias, somos a escolha ideal para o cuidado com a sua rede elétrica.","destaque":"Comércio de rua e estabelecimentos comerciais exigem sistemas elétricos robustos para sustentar equipamentos de alto fluxo. O uso prolongado de maquinário e iluminação intensa exige vistorias periódicas para evitar paradas inesperadas nas operações. Nossa equipe identifica riscos de incêndio e ineficiência energética no layout comercial. Trabalhamos para que sua empresa funcione sem interrupções por falhas na fiação elétrica.","sinais":"Disjuntor principal aquecendo ao toque\nCheiro característico de ozônio ou plástico queimado\nOscilação de iluminação ao ligar motores ou máquinas\nFiação exposta em áreas de circulação comum","servicos":"Quadro de distribuição: Reformamos ou organizamos seu painel elétrico principal.\nCurto-circuito: Resolvemos problemas críticos de falhas elétricas no seu local.\nChuveiro elétrico: Instalamos equipamentos com segurança e vedação correta.\nTomadas e interruptores: Realizamos a troca preventiva e corretiva desses componentes.\nManutenção predial: Oferecemos soluções completas de conservação elétrica para imóveis.","faq":"[{\"q\":\"Qual a qualificação da equipe?\",\"a\":\"A Mestre dos Reparos conta com responsável técnico formado em engenharia. Garantimos conhecimento profundo para resolver problemas elétricos de qualquer complexidade.\"},{\"q\":\"Como solicitar um orçamento?\",\"a\":\"Você pode entrar em contato através dos nossos canais de atendimento. Analisamos sua necessidade para propor a solução técnica mais adequada.\"},{\"q\":\"Vocês possuem CNPJ?\",\"a\":\"Sim, somos uma empresa formalizada em Barueri. Nossa atuação é pautada pela transparência e legalidade com o fornecimento de nota fiscal.\"},{\"q\":\"A NBR 5410 é obrigatória?\",\"a\":\"Ela é a norma técnica que rege instalações elétricas de baixa tensão no Brasil. Segui-la garante segurança, eficiência e evita acidentes em seu imóvel.\"},{\"q\":\"Atendem grandes comércios?\",\"a\":\"Com certeza, nossa experiência abrange desde residências até prédios comerciais. Ajustamos nossas técnicas às necessidades específicas de cada tipo de construção.\"}]"};
const mapa: Record<string,string> = {};
for (const l of LOCAIS) mapa[l.chave] = `${SITE}/p/${l.slug}.html`;
const b = LOCAIS.find((l) => l.chave === 'barueri')!;
const enc = (s: string) => btoa(String.fromCharCode(...new TextEncoder().encode(s).reduce((a: number[], x) => (a.push(x), a), [])));
const paginas = LOCAIS.map((l) => ({ title: tituloDaPagina(l), url: mapa[l.chave] }));
const e = renderPagina(b, conteudo, mapa), h = homeHtml(paginas);
await Deno.writeTextFile('/app/.out1.html', e); await Deno.writeTextFile('/app/.out2.html', h);
EOF
deno run -A ./gerar_tmp.ts && rm -f ./gerar_tmp.ts && base64 -w0 .out1.html && echo && echo SEP && base64 -w0 .out2.html; rm -f .out1.html .out2.html